const response = $input.item.json.choices[0].message.content;
let outline;

try {
  outline = JSON.parse(response);
} catch (e) {
  const jsonMatch = response.match(/```json\s*([\s\S]*?)\s*```/);
  if (jsonMatch) {
    outline = JSON.parse(jsonMatch[1]);
  } else {
    const jsonMatch2 = response.match(/\{[\s\S]*\}/);
    if (jsonMatch2) {
      outline = JSON.parse(jsonMatch2[0]);
    } else {
      throw new Error("Could not parse outline response as JSON: " + response.substring(0, 200));
    }
  }
}

const originalInput = $('Build Outline Request').first().json;
const topic = originalInput.topic;
const video_name = originalInput.video_name;
const voice_id = originalInput.voice_id;
const script_type = originalInput.script_type;

return outline.sections.map((section, index) => ({
  json: {
    topic: topic,
    video_name: video_name,
    voice_id: voice_id,
    script_type: script_type,
    full_title: outline.title,
    hook_question: outline.hook_question,
    total_sections: outline.sections.length,
    full_outline: outline.sections,
    current_section: section,
    section_index: index,
    is_opening: section.number === 1,
    is_final: section.number === outline.sections.length
  }
}));

const sectionContent = $input.item.json.choices[0].message.content;
const loopData = $('Loop Over Sections').item.json;

const staticData = $getWorkflowStaticData('global');

// Extract the first sentence/opening phrase (first 50 chars or until first period)
const openingPhrase = sectionContent.substring(0, 100).split('.')[0];

// Initialize or append to used openings list
if (!staticData.usedOpenings) {
  staticData.usedOpenings = [];
}
staticData.usedOpenings.push(openingPhrase);

// Save content for next iteration
staticData.lastSectionContent = sectionContent;
staticData.lastSectionNumber = loopData.current_section.number;

// Format the section with header
const formattedSection = `# **Section ${loopData.current_section.number}: ${loopData.current_section.title}**\n\n${sectionContent}`;

return [{
  json: {
    topic: loopData.topic,
    video_name: loopData.video_name,
    voice_id: loopData.voice_id,
    full_title: loopData.full_title,
    total_sections: loopData.total_sections,
    section_number: loopData.current_section.number,
    section_title: loopData.current_section.title,
    section_content: formattedSection,
    raw_content: sectionContent,
    word_count: sectionContent.split(/\s+/).length
  }
}];

const sections = $input.item.json.all_sections;

// Sort by section number to ensure correct order
sections.sort((a, b) => a.section_number - b.section_number);

// Combine all sections with separator
const fullScript = sections.map(s => s.section_content).join('\n\n---\n\n');

// Calculate total word count
const totalWords = sections.reduce((sum, s) => sum + s.word_count, 0);

// Get metadata from first section
const metadata = sections[0];

return [{
  json: {
    topic: metadata.topic,
    video_name: metadata.video_name,
    voice_id: metadata.voice_id,
    full_title: metadata.full_title,
    total_sections: metadata.total_sections,
    total_words: totalWords,
    full_script: fullScript,
    sections: sections
  }
}];

// Clear staticData from any previous workflow runs
const staticData = $getWorkflowStaticData('global');
staticData.lastSectionContent = null;
staticData.lastSectionNumber = null;
staticData.usedOpenings = [];

// Pass through all input data unchanged
return $input.all();

// Get today's date in YYYY-MM-DD format
const today = new Date().toISOString().split('T')[0];

// Get all rows from sheet
const allRows = $input.all();

// Count scripts completed today
const completedToday = allRows.filter(row => {
  const completedDate = row.json.date_completed;
  if (!completedDate) return false;
  // Handle different date formats
  const dateStr = typeof completedDate === 'string' 
  ? completedDate.split(' ')[0]  // ✅ Splits on space for "yyyy-MM-dd HH:mm:ss"
  : new Date(completedDate).toISOString().split('T')[0];
  return dateStr === today;
}).length;

// Set your daily limit here (adjust as needed)
const DAILY_LIMIT = 15; // Change to 4 or 5 if you want

// Calculate how many more we can do today
const remainingSlots = DAILY_LIMIT - completedToday;

// Filter for pending topics (no doc_id means not processed yet)
const pendingTopics = allRows.filter(row => !row.json.doc_id);

// Take only the number we can process today
const topicsToProcess = pendingTopics.slice(0, Math.max(0, remainingSlots));

// Return results with metadata
return topicsToProcess.map(row => ({
  json: {
    ...row.json,
    _metadata: {
      completedToday: completedToday,
      dailyLimit: DAILY_LIMIT,
      remainingSlots: remainingSlots,
      totalPending: pendingTopics.length
    }
  }
}));

const row = $input.item.json;

return [{
  json: {
    topic: row.topic,
    video_name: row.video_name,
    target_words: parseInt(row.target_words),
    voice_id: row.voice_id || 'AeRdCCKzvd23BpJoofzx', // default if empty
    script_type: row.script_type || 'deep_dive',
    // Preserve original row data for later update
    _original_row: row
  }
}];

// Apply Replacements Node - v2 (with overlap detection)
// Paste this into your "Apply Replacements" Code node in n8n

const scriptData = $('Extract Script Text').first().json;
const qcResponse = $('Parse QC Response').first().json;

let currentText = scriptData.scriptText;
const replacements = qcResponse.replacements || [];

const results = {
  applied: [],
  failed: [],
  skippedOverlap: []
};

// Helper: Normalize whitespace for flexible matching
function normalizeWhitespace(str) {
  return str.replace(/\s+/g, ' ').trim();
}

// Helper: Check word boundaries
function isWordBoundaryMatch(text, startIndex, matchLength) {
  const beforeChar = startIndex > 0 ? text[startIndex - 1] : ' ';
  const afterChar = startIndex + matchLength < text.length ? text[startIndex + matchLength] : ' ';
  const wordBoundary = /[\s.,!?;:'"()\[\]{}\-—–\n\r]/;
  return (startIndex === 0 || wordBoundary.test(beforeChar)) &&
         (startIndex + matchLength === text.length || wordBoundary.test(afterChar));
}

// Helper: Find text with flexible whitespace
function findWithFlexibleWhitespace(text, searchStr) {
  const normalizedSearch = normalizeWhitespace(searchStr);
  const searchRegex = normalizedSearch
    .replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    .replace(/ /g, '\\s+');

  const regex = new RegExp(searchRegex, 'g');
  const matches = [];
  let match;

  while ((match = regex.exec(text)) !== null) {
    if (isWordBoundaryMatch(text, match.index, match[0].length)) {
      matches.push({
        index: match.index,
        length: match[0].length,
        matchedText: match[0]
      });
    }
  }

  return matches;
}

// Step 1: Find all match positions FIRST
const replacementsWithPositions = [];

for (const replacement of replacements) {
  const findText = replacement.find;

  // Skip truncated entries
  if (findText.endsWith('...') || findText.length < 10) {
    results.failed.push({
      find: findText.substring(0, 50) + '...',
      reason: 'Find text too short or truncated'
    });
    continue;
  }

  const matches = findWithFlexibleWhitespace(currentText, findText);

  if (matches.length === 0) {
    results.failed.push({
      find: findText.substring(0, 50) + '...',
      reason: 'Text not found in script'
    });
    continue;
  }

  if (matches.length > 1) {
    results.failed.push({
      find: findText.substring(0, 50) + '...',
      reason: 'Multiple matches found (' + matches.length + ') - need more specific text'
    });
    continue;
  }

  replacementsWithPositions.push({
    ...replacement,
    startIndex: matches[0].index,
    endIndex: matches[0].index + matches[0].length,
    matchedText: matches[0].matchedText
  });
}

// Step 2: Sort by position (END to START) to avoid index shifting
replacementsWithPositions.sort((a, b) => b.startIndex - a.startIndex);

// Step 3: Detect and skip overlapping replacements
const appliedRanges = [];

for (const replacement of replacementsWithPositions) {
  // Check if this replacement overlaps with any already-applied replacement
  const overlaps = appliedRanges.some(range =>
    (replacement.startIndex < range.end && replacement.endIndex > range.start)
  );

  if (overlaps) {
    results.skippedOverlap.push({
      find: replacement.find.substring(0, 50) + '...',
      reason: 'Skipped - overlaps with another replacement'
    });
    continue;
  }

  // Apply the replacement
  currentText =
    currentText.substring(0, replacement.startIndex) +
    replacement.replace +
    currentText.substring(replacement.endIndex);

  // Track this range (adjusted for the new text length)
  appliedRanges.push({
    start: replacement.startIndex,
    end: replacement.startIndex + replacement.replace.length
  });

  results.applied.push({
    rule: replacement.rule_violated || 'unspecified',
    priority: replacement.priority || 'medium',
    original: replacement.matchedText.substring(0, 50) + (replacement.matchedText.length > 50 ? '...' : ''),
    replacement: replacement.replace.substring(0, 50) + (replacement.replace.length > 50 ? '...' : '')
  });
}

return [{
  json: {
    documentId: scriptData.documentId,
    updatedText: currentText,
    originalLength: scriptData.scriptText.length,
    newLength: currentText.length,
    stats: {
      totalReplacements: replacements.length,
      appliedSuccessfully: results.applied.length,
      failed: results.failed.length,
      skippedOverlap: results.skippedOverlap.length
    },
    appliedChanges: results.applied,
    failedReplacements: results.failed,
    skippedReplacements: results.skippedOverlap,
    assessment: qcResponse.assessment
  }
}];

const response = $input.first().json;
const previousData = $('Prepare QC Prompt').first().json;

// Extract the content from OpenRouter's response format
let content = response.choices?.[0]?.message?.content || response.content || '';

// Clean up the response (remove any markdown code fences if present)
content = content.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();

// Parse the JSON
let parsed;
try {
  parsed = JSON.parse(content);
} catch (e) {
  // If parsing fails, try to extract JSON from the response
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      parsed = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      throw new Error('Failed to parse JSON from AI response: ' + e.message + '\n\nRaw content: ' + content.substring(0, 500));
    }
  } else {
    throw new Error('No JSON found in AI response: ' + content.substring(0, 500));
  }
}

// Validate structure
if (!parsed.assessment) {
  parsed.assessment = {
    word_count: previousData.wordCount,
    second_person_immersion_score: 0,
    comedically_appalled_tone_score: 0,
    pacing_score: 0,
    reflection_beat_status: 'unknown',
    hard_no_count: 0,
    ready_for_production: false,
    production_blockers: ['Could not parse assessment']
  };
}

if (!Array.isArray(parsed.replacements)) {
  parsed.replacements = [];
}

return [{
  json: {
    documentId: previousData.documentId,
    scriptText: previousData.scriptText,
    endIndex: previousData.endIndex,
    assessment: parsed.assessment,
    replacements: parsed.replacements,
    replacementCount: parsed.replacements.length,
    readyForProduction: parsed.assessment.ready_for_production
  }
}];

// Extract plain text from Google Docs response (Simplify mode)
const doc = $input.first().json;
const documentId = $json.documentId;

// With Simplify ON, content comes as a direct string
const scriptText = doc.content || '';

// Calculate approximate end index for the update
// Google Docs indices are 1-based, and we need the position after the last character
const endIndex = scriptText.length + 1;

return [{
  json: {
    documentId,
    scriptText,
    endIndex,
    wordCount: scriptText.split(/\s+/).filter(w => w.length > 0).length
  }
}];

